window.__ModuleLoader__.load({ id: '@andrey/dsh-andrey-extra', factory: require => {
  const module = { exports: {} }
  const exports = module.exports

  const react = require('react')
  const primitives = require('@deepseek-ai/dsh-client-ui-primitives')

  /** Shown under the wordmark so a copy is never mistaken for the original. */
  const VERSION_LABEL = 'Andrey Version 0.5.2'

  /** How much of the transcript tail travels with the handoff, in characters. */
  const HANDOFF_TAIL_CHARS = 12000
  /** First user message budget, so the original goal survives a long tail cut. */
  const HANDOFF_GOAL_CHARS = 700

  function firstUserBlock(markdown) {
    const lines = markdown.split('\n')
    const block = []
    let started = false
    for (const line of lines) {
      if (line.startsWith('>')) {
        started = true
        block.push(line.replace(/^>\s?/, ''))
        continue
      }
      if (started) break
    }
    return block.join('\n').trim().slice(0, HANDOFF_GOAL_CHARS)
  }

  function tailBlock(markdown) {
    const sliced = markdown.length > HANDOFF_TAIL_CHARS ? markdown.slice(-HANDOFF_TAIL_CHARS) : markdown
    if (sliced.length === markdown.length) return sliced.trim()
    const aligned = sliced.search(/\n(?:>\s|\*\*Assistant\*\*)/)
    const body = aligned > 0 ? sliced.slice(aligned + 1) : sliced
    return body.trim()
  }

  function buildHandoff({ sessionId, title, cwd, markdown }) {
    const goal = firstUserBlock(markdown)
    const tail = tailBlock(markdown)
    return [
      `# Handoff: ${title || `Session ${sessionId}`}`,
      '',
      'You are taking over this work from a previous session. The context below is established state: do not redo finished work and do not ask the user to repeat it.',
      '',
      `- Source session: ${sessionId}`,
      `- Workspace: ${cwd || 'unchanged'}`,
      `- Transferred: ${new Date().toISOString()}`,
      ...goal === '' ? [] : ['', '## Original goal', '', goal],
      '',
      '## Latest context',
      '',
      tail,
      '',
      '## Your task',
      '',
      'Continue from where this session stopped. Verify the current state in the workspace first, then proceed with the next concrete step. If the goal is ambiguous, ask one clarifying question before changing anything.',
      '',
    ].join('\n')
  }

  async function readHandoff(ctx, sessionId, displayTitle) {
    const route = `api/session.markdown?${new URLSearchParams({ sessionId: String(sessionId) }).toString()}`
    const response = await fetch(route)
    if (!response.ok) throw new Error(`HTTP ${response.status}`)
    const markdown = await response.text()
    const row = ctx.sessions.list.getSnapshot().byId[sessionId]
    const title = displayTitle || row?.projectionValues?.title || row?.title || ''
    return buildHandoff({ sessionId, title, cwd: row?.cwd, markdown })
  }

  async function copyHandoff(ctx, sessionId, displayTitle) {
    try {
      const text = await readHandoff(ctx, sessionId, displayTitle)
      const copied = await primitives.writeClipboard(text)
      ctx.contextMenus.notify(copied ? 'Handoff copied to clipboard.' : 'Clipboard write failed.', copied === true)
    } catch (error) {
      ctx.contextMenus.notify(`Could not read the session: ${String(error?.message ?? error)}`, false)
    }
  }

  async function startHandoff(ctx, sessionId, displayTitle) {
    try {
      const text = await readHandoff(ctx, sessionId, displayTitle)
      const workspace = ctx.workspaces.list.getSnapshot().items.find(item => item.sessionIds.includes(sessionId))
      ctx.uiWorkspace.startSession(workspace?.workspaceId, { prompt: text, whenDraftExists: 'replace' })
      ctx.contextMenus.notify('Handoff loaded into a new session. Review and send.', true)
    } catch (error) {
      ctx.contextMenus.notify(`Could not start the handoff: ${String(error?.message ?? error)}`, false)
    }
  }

  /**
   * The brand name slot of the sidebar's logo row.
   *
   * Their wordmark is reused as-is (`includeMark: false`, because the mark has
   * its own slot); the caption sits directly beneath it in the same column, so
   * the logo row keeps its existing height and drag behaviour.
   */
  function BrandNameWithVersion() {
    return react.createElement(
      'span',
      { style: { display: 'inline-flex', flexDirection: 'column', alignItems: 'flex-start', lineHeight: 1, gap: '3px' } },
      react.createElement(primitives.BrandWordmark, { includeMark: false }),
      react.createElement(
        'span',
        {
          style: {
            fontSize: '10px',
            letterSpacing: '0.06em',
            opacity: 0.62,
            fontVariant: 'small-caps',
            whiteSpace: 'nowrap',
          },
          title: VERSION_LABEL,
        },
        VERSION_LABEL,
      ),
    )
  }

  const inject = ['slots', 'contextMenus', 'sessions', 'workspaces', 'uiWorkspace']

  /** The chat currently shown in the main view, if any. */
  function mainSession(ctx) {
    const rows = Object.values(ctx.sessions.list.getSnapshot().byId)
    const row = rows.find(item => (item?.retainedBy?.mainView ?? 0) > 0)
    if (row === undefined) return undefined
    return { sessionId: row.id, title: row.projectionValues?.title || row.title || '' }
  }

  /**
   * Same actions for surfaces that live outside the context-menu system, such
   * as the fork's own "More" menu in the injected bundle: it cannot reach the
   * cordis services, so it calls this bridge instead.
   */
  function installBridge(ctx) {
    const bridge = {
      version: VERSION_LABEL,
      open(point) {
        const main = mainSession(ctx)
        if (main === undefined) {
          ctx.contextMenus.notify('Open a chat first.', false)
          return
        }
        ctx.contextMenus.open({ kind: 'session', value: { sessionId: main.sessionId, displayTitle: main.title } }, point)
      },
      copy() {
        const main = mainSession(ctx)
        if (main === undefined) return Promise.resolve(false)
        return copyHandoff(ctx, main.sessionId, main.title).then(() => true)
      },
      start() {
        const main = mainSession(ctx)
        if (main === undefined) return Promise.resolve(false)
        return startHandoff(ctx, main.sessionId, main.title).then(() => true)
      },
    }
    window.__andreyHandoff = bridge
    return () => {
      if (window.__andreyHandoff === bridge) delete window.__andreyHandoff
    }
  }

  function apply(ctx) {
    ctx.effect(() => installBridge(ctx))

    ctx.slots.inject('sidebar.brand.name', () => ctx.slots.register({ name: 'sidebar.brand.name' }, BrandNameWithVersion))

    ctx.slots.inject('contextMenu.icon', () => ctx.slots.register(
      { name: 'contextMenu.icon', key: 'andrey.handoff' },
      primitives.IconPaperPlaneOutlineRegular,
    ))

    for (const target of ['session', 'sessionHeader', 'tab']) {
      ctx.effect(() => ctx.contextMenus.register({
        id: 'andrey.handoff',
        target,
        order: 300,
        resolve: ({ sessionId, displayTitle }) => [{
          id: 'handoff',
          label: 'Hand Off to Another Agent',
          icon: { key: 'andrey.handoff' },
          children: [
            {
              id: 'copy',
              label: 'Copy Handoff to Clipboard',
              run: () => copyHandoff(ctx, sessionId, displayTitle),
            },
            {
              id: 'start',
              label: 'Start New Session From Here',
              run: () => startHandoff(ctx, sessionId, displayTitle),
            },
          ],
        }],
      }), `andrey-extra: handoff menu (${target})`)
    }
  }

  exports.apply = apply
  exports.inject = inject
  exports.buildHandoff = buildHandoff
  return module.exports
} })
